/* Вес каждого селектора как (a, b, c) */
h1          { /* (0,0,1) */ }
.card       { /* (0,1,0) */ }
ul li       { /* (0,0,2) */ }
a:hover     { /* (0,1,1) */ }
.card .title{ /* (0,2,0) */ }
#nav .item  { /* (1,1,0) */ }

/* p проиграет .text на любом элементе:
   (0,0,1) слабее (0,1,0) */

// Симулятор специфичности: считает (a, b, c) — модель алгоритма CSS, не браузер.
function specificity(selector) {
  var a = 0, b = 0, c = 0;
  var pieces = selector.split(">").join(" ").split(" ");
  for (var i = 0; i < pieces.length; i++) {
    var p = pieces[i];
    if (p === "" || p === "*") { continue; }
    var j = 0;
    while (j < p.length) {
      if (p.slice(j, j + 2) === "::") {
        c++;
        j += 2;
        while (j < p.length && "#.:".indexOf(p[j]) === -1) { j++; }
        continue;
      }
      var mark = p[j];
      var k = j + 1;
      while (k < p.length && "#.:".indexOf(p[k]) === -1) { k++; }
      if (mark === "#") { a++; }
      else if (mark === "." || mark === ":") { b++; }
      else { c++; }
      j = k;
    }
  }
  return [a, b, c];
}
var selectors = ["h1", ".card", "ul li", "a:hover", ".card .title", "#nav .item"];
var best = "";
for (var i = 0; i < selectors.length; i++) {
  var s = specificity(selectors[i]);
  console.log(selectors[i] + " -> (" + s[0] + "," + s[1] + "," + s[2] + ")");
  var bs = best === "" ? null : specificity(best);
  var stronger = bs === null
    || s[0] > bs[0]
    || (s[0] === bs[0] && s[1] > bs[1])
    || (s[0] === bs[0] && s[1] === bs[1] && s[2] > bs[2]);
  if (stronger) { best = selectors[i]; }
}
console.log("strongest: " + best + " -> (" + specificity(best).join(",") + ")");

