}

// Симулятор единиц: перевод px -> rem при корне 16px.
// Модель арифметики, а не рендеринг браузера.
var root = 16;
var px = [12, 16, 18, 20, 24, 32];
for (var i = 0; i < px.length; i++) {
  console.log(px[i] + "px = " + (px[i] / root) + "rem");
}
console.log("1.5rem at root 16px = " + (1.5 * root) + "px");
console.log("2em inside p { font-size: 20px } = " + (2 * 20) + "px");
console.log("50% of a 400px parent = " + (400 * 0.5) + "px");

