// Симулятор box model: видимая и занятая ширина (модель счёта, не рендеринг).
function visibleWidth(content, padding, border) {
  return content + 2 * padding + 2 * border;
}
var boxes = [
  { name: "card", content: 200, padding: 16, border: 2, margin: 8 },
  { name: "badge", content: 60, padding: 6, border: 1, margin: 4 }
];
