  var b = boxes[i];
  var w = visibleWidth(b.content, b.padding, b.border);
  console.log(b.name + ": content " + b.content + " + padding 2x" + b.padding + " + border 2x" + b.border + " = visible " + w + "px");
  console.log(b.name + ": visible " + w + " + margin 2x" + b.margin + " = occupied " + (w + 2 * b.margin) + "px");
}

