/* block: с новой строки, вся ширина, все размеры работают */
.block-demo {
  display: block;
  background: #dbeafe;
}

/* inline: внутри строки, размеры игнорируются */
.inline-demo {
  display: inline;
  background: #fecaca;
  width: 200px;      /* не сработает */
  padding: 20px;     /* вертикальная часть налезет на соседние строки */
}

/* inline-block: в строке, но принимает размеры */
.chip {
  display: inline-block;
  background: #d1fae5;
  width: 120px;
  padding: 8px 16px;
}

/* Способ 1: элемента как будто нет */
.gone {
  display: none;
}

/* Способ 2: невидим, но место занято */
.invisible {
  visibility: hidden;
}

/* Способ 3: прозрачен, место занято, но
   по нему всё ещё можно пройти Tab-ом */
.transparent {
  opacity: 0;
}

/* По умолчанию: смещения не работают */
.plain {
  position: static;
  /* top: 20px;  <- игнорируется */
}

/* Сдвиг от обычного места, место сохранено */
.nudged {
  position: relative;
  top: 20px;    /* вниз на 20px */
  left: 24px;   /* вправо на 24px */
}

/* Подготовка к завтрашнему дню:
   relative-родитель — система координат
   для absolute-детей */
.stage {
  position: relative;
}

/* Родитель — система координат */
.card {
  position: relative;
}
.badge {
  position: absolute;
  top: 8px;
  right: 8px;
  padding: 4px 8px;
  background: #dc2626;
  color: #fff;
}

/* Прилипание к окну браузера */
.site-header {
  position: fixed;
  top: 0;
  left: 0;
  right: 0;
}

/* Гибрид: в потоке до порога, потом липнет */
.list-title {
  position: sticky;
  top: 0;
  background: #fff;
}

/* z-index без position — игнорируется! */
.bad-without-position {
  z-index: 9999; /* не сработает */
}

/* Работает: позиционированный элемент */
.site-header {
  position: fixed;
  top: 0;
  z-index: 20;
}
.modal {
  position: fixed;
  inset: 0;
  z-index: 30;
}

/* Ловушка: opacity < 1 создаёт контекст,
   и z-index детей не выйдет за его пределы */
.faded-card {
  opacity: 0.9;
  position: relative;
  z-index: 5;
}

/* Контейнер */
.toolbar {
  display: flex;
  flex-direction: row;      /* по умолчанию */
  align-items: center;      /* вертикаль */
  justify-content: space-between;
  gap: 12px;
  height: 64px;
}

/* Центрирование по двум осям */
.hero {
  display: flex;
  justify-content: center;
  align-items: center;
  min-height: 100vh;
}

/* Столбец вместо ряда */
.stack {
  display: flex;
  flex-direction: column;
  gap: 16px;
}

// Симулятор flex: распределение свободного места между flex-grow (модель счёта).
var container = 900, gap = 20;
var items = [
  { name: "logo", basis: 200, grow: 1 },
  { name: "search", basis: 250, grow: 2 },
  { name: "menu", basis: 150, grow: 1 }
];
var gaps = gap * (items.length - 1);
var bases = 0;
for (var i = 0; i < items.length; i++) { bases += items[i].basis; }
var free = container - bases - gaps;
var growSum = 0;
for (var i = 0; i < items.length; i++) { growSum += items[i].grow; }
console.log("container " + container + "px, gaps " + gaps + "px, bases " + bases + "px");
console.log("free space = " + free + "px, grow sum = " + growSum);
for (var i = 0; i < items.length; i++) {
  var extra = free * items[i].grow / growSum;
  console.log(items[i].name + ": " + items[i].basis + " + " + extra + " = " + (items[i].basis + extra) + "px");
}

