.hero {
  display: flex;
  justify-content: center;
  align-items: center;
  min-height: 100vh;
}

/* Фикс + доли */
.layout {
  display: grid;
  grid-template-columns: 200px 1fr 2fr;
  gap: 20px;
}

/* Три равные колонки */
.gallery {
  display: grid;
  grid-template-columns: repeat(3, 1fr);
  gap: 16px;
}

/* Сколько влезет колонок по 180px */
.auto-gallery {
  display: grid;
  grid-template-columns: repeat(auto-fill, minmax(180px, 1fr));
  gap: 16px;
}

