.page > aside  { grid-area: sidebar; }
.page > main   { grid-area: main; }
.page > footer { grid-area: footer; }

/* Растягивание ячеек */
.wide {
  grid-column: span 2;
}

/* Галерея: сколько колонок влезет */
.gallery {
  display: grid;
  grid-template-columns: repeat(auto-fill, minmax(180px, 1fr));
  gap: 16px;
}

/* Дашборд */
.dashboard {
  display: grid;
  grid-template-areas:
    "header header"
    "sidebar main"
    "footer footer";
  grid-template-columns: 240px 1fr;
  grid-template-rows: auto 1fr auto;
  min-height: 100vh;
}

/* Виджеты внутри main */
.widgets {
  display: grid;
  grid-template-columns: repeat(auto-fit, minmax(220px, 1fr));
  gap: 16px;
}
.widget {
  display: flex;
  flex-direction: column;
  gap: 8px;
}

/* База: мобильная колонка */
.page {
  display: grid;
  grid-template-columns: 1fr;
  gap: 16px;
}
.nav { display: none; }

/* Планшет: две колонки, меню видно */
@media (min-width: 600px) {
  .page { grid-template-columns: 1fr 1fr; }
  .nav { display: flex; }
}

/* Десктоп: три колонки */
@media (min-width: 900px) {
  .page { grid-template-columns: repeat(3, 1fr); }
}

/* Диапазон */
@media (min-width: 600px) and (max-width: 899px) {
  .hero { font-size: 1.5rem; }
}

// Симулятор media queries: какой набор правил активен (модель каскада media).
var breakpoints = [
  { min: 0, name: "base (mobile-first)" },
  { min: 600, name: "min-width: 600px" },
  { min: 900, name: "min-width: 900px" }
];
var widths = [360, 600, 900, 1280];
for (var w = 0; w < widths.length; w++) {
  var active = breakpoints[0];
  for (var i = 0; i < breakpoints.length; i++) {
    if (widths[w] >= breakpoints[i].min) { active = breakpoints[i]; }
  }
  console.log(widths[w] + "px viewport -> " + active.name);
}

