/* Плавный заголовок без лестницы media queries */
h1 {
  font-size: clamp(1.75rem, 4vw, 3rem);
  line-height: 1.2;
}
p {
  font-size: 1rem;
  line-height: 1.6;
}

/* Комфортная длина строки */
.prose {
  max-width: 65ch;
  margin-inline: auto;
}

/* Золотая формула картинок */
img {
  max-width: 100%;
  height: auto;
}
.cover {
  aspect-ratio: 16 / 9;
  object-fit: cover;
  width: 100%;
}

/* Скругления и подъём */
.card {
  border-radius: 12px;
  box-shadow: 0 2px 4px rgba(15, 23, 42, 0.1),
              0 12px 24px rgba(15, 23, 42, 0.08);
}

/* Плавный переход */
.button {
  background: #2563eb;
  transition: background-color 0.2s ease, box-shadow 0.2s ease;
}
.button:hover {
  background: #1d4ed8;
  box-shadow: 0 6px 16px rgba(37, 99, 235, 0.35);
}

/* Пилюля и круг */
.pill  { border-radius: 999px; }
.round { border-radius: 50%; }

/* Определение движения */
@keyframes pulse {
  0%   { opacity: 1; }
  50%  { opacity: 0.4; }
  100% { opacity: 1; }
}
.status-dot {
  width: 10px;
  height: 10px;
  border-radius: 50%;
  background: #16a34a;
  animation: pulse 1.5s ease-in-out infinite;
}

/* Уважение к настройке пользователя */
@media (prefers-reduced-motion: reduce) {
  .status-dot { animation: none; }
  * {
    transition-duration: 0.01ms;
    animation-duration: 0.01ms;
  }
}

/* Контраст: проходит AA */
.text-ok { color: #1e293b; background: #ffffff; }
.text-muted { color: #475569; background: #ffffff; }

/* Видимый фокус для клавиатуры */
.button:focus-visible {
  outline: 3px solid #2563eb;
  outline-offset: 2px;
}

/* Маленькая иконка с большой зоной нажатия */
.icon-button {
  width: 24px;
  height: 24px;
  padding: 12px; /* зона нажатия 48x48 */
  box-sizing: content-box;
}

/* Ошибка — не только цветом */
.field-error {
  border: 2px solid #dc2626;
}
.field-error + .hint { color: #dc2626; }

/* Итоговый скелет страницы профиля */
*, *::before, *::after { box-sizing: border-box; }
